static int countPositive(int arr[], int i, int n) {
    if (i >= n) return 0;
    int add = (arr[i] > 0) ? 1 : 0;
    return add + countPositive(arr, i + 1, n);
}

int main(void) {
    int n;
    scanf("%d", &n);
    int arr[1000];
    for (int i = 0; i < n; i++) scanf("%d", &arr[i]);
    printf("%d\n", countPositive(arr, 0, n));
    return 0;
}

